package com.example.yuejie;
import android.view.*;
/** Gesture decisions do not draw pages or perform chapter I/O. */
final class ReaderGestureController {
 final ReaderSurface s;final int slop,minVelocity,maxVelocity;final float horizontalVelocity;float rawDx;
 ReaderGestureController(ReaderSurface surface){s=surface;ViewConfiguration c=ViewConfiguration.get(s.getContext());slop=c.getScaledTouchSlop();minVelocity=c.getScaledMinimumFlingVelocity();maxVelocity=c.getScaledMaximumFlingVelocity();horizontalVelocity=s.d(100);}
 boolean complete(float vx){if(s.activeMode==PageTurnMode.NONE)return Math.abs(rawDx)>s.getWidth()/3f||Math.abs(vx)>minVelocity;return Math.abs(vx)>horizontalVelocity||(s.activeMode==PageTurnMode.SIMULATION?(s.direction>0?s.lastX<s.getWidth()/2f:s.lastX>s.getWidth()/2f):Math.abs(s.drag)>s.getWidth()/2f);}
 boolean touch(MotionEvent e){if(s.frame==null||!s.host.canTurn())return true;int action=e.getActionMasked();if(action==MotionEvent.ACTION_DOWN){if(s.animating())s.finishTurn();s.refreshVisuals();s.warmNow();s.downX=s.lastX=e.getX();s.downY=s.lastY=e.getY();s.dragging=false;s.vertical=false;s.direction=0;s.target=null;rawDx=0;s.velocity=VelocityTracker.obtain();s.velocity.addMovement(e);return true;}
 if(s.animating())return true;if(s.velocity!=null)s.velocity.addMovement(e);
 if(action==MotionEvent.ACTION_MOVE){rawDx=e.getX()-s.downX;float dy=e.getY()-s.downY;if(!s.dragging&&!s.vertical&&Math.abs(dy)>slop&&Math.abs(dy)>Math.abs(rawDx))s.vertical=true;if(!s.vertical&&!s.dragging&&Math.abs(rawDx)>slop&&Math.abs(rawDx)>Math.abs(dy)){s.dragging=true;s.direction=rawDx<0?1:-1;s.target=s.neighbor(s.direction);if(s.target!=null)s.renderer.prepare(s,s.frame,s.target);}
 if(s.dragging){int dir=rawDx<0?1:-1;if(dir!=s.direction&&Math.abs(rawDx)>slop){s.direction=dir;s.target=s.neighbor(dir);if(s.target!=null)s.renderer.prepare(s,s.frame,s.target);}s.lastX=e.getX();s.lastY=e.getY();float factor=s.target==null?.1f:(s.activeMode==PageTurnMode.SIMULATION?1f:.9f);s.drag=Math.max(-s.getWidth(),Math.min(s.getWidth(),rawDx*factor));if(s.activeMode!=PageTurnMode.NONE)s.requestScene();}s.lastX=e.getX();s.lastY=e.getY();return true;}
 if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL){boolean cancel=action==MotionEvent.ACTION_CANCEL;float vx=0;if(s.velocity!=null){s.velocity.computeCurrentVelocity(1000,maxVelocity);vx=s.velocity.getXVelocity();s.velocity.recycle();s.velocity=null;}if(s.dragging){rawDx=e.getX()-s.downX;boolean finish=!cancel&&complete(vx);if(finish&&Math.abs(vx)>(s.activeMode==PageTurnMode.NONE?minVelocity:horizontalVelocity)){int dir=vx<0?1:-1;if(dir!=s.direction){s.direction=dir;s.target=s.neighbor(dir);if(s.target!=null)s.renderer.prepare(s,s.frame,s.target);}}
 if(s.target==null){int dir=s.direction;boolean needs=finish;s.resetMotion();s.flushVisuals();if(s.activeMode!=PageTurnMode.NONE)s.requestScene();if(needs)s.host.needChapter(dir);}else s.animateTo(finish?(s.direction>0?-s.getWidth():s.getWidth()):0,finish);
 }else if(!cancel&&!s.vertical&&Math.abs(e.getY()-s.downY)<slop&&Math.abs(e.getX()-s.downX)<slop){s.performClick();int paragraph=s.hitComment(e.getX(),e.getY());if(paragraph>=0)s.host.paragraph(paragraph);else if(e.getX()<s.getWidth()*.3f)s.turn(-1);else if(e.getX()>s.getWidth()*.7f)s.turn(1);else s.host.center();}else{s.resetMotion();s.flushVisuals();}return true;}return true;}
}
